// TH16 v1.00a Extra final boss, Boss8 (8th non-spell).
// Source: st07bs.ecl.txt:768-828 (entry) + Boss8_at 830-853 (dependency).
// Entry state: BossCard7 interrupt handoff; the source recenters to (0,128) with its
// own movePosTime(60,4,0,128), so the standalone boss is created there.
const TIME_LIMIT: int = 4324;      // 120 shell buffer + 4200 source window + 4
const OPENING_BUFFER: int = 120;

// etSprite(0,10,4): TH16 type 10 (SHARD) color 4.
const TH16_SHARD: int = 512;

// Boss8_at A argument: +0.113662824 rad per 5-frame volley (~1185.5 BAM).
const RING_STEP: int = 1186;

// ---- Boss8_at: etAim mode 3 (fixed ring), etCount 11x2, etSpeed 4.0/3.8,
// 30 volleys 5 frames apart, base angle starts at ANGLE_PLAYER and steps by A.
// Layer q=0 speed 4.0, q=1 speed 3.8 (etSpeed endpoints over M=2).
// etEx type 2 (ANIM, a=1) keeps the birth retro-displacement only:
// net birth distance = etDist(32) - 4*speed -> 16 / 16.8 along each bullet angle.
async sub boss8_at(step: angle) {
    var a: angle = aim_player();   // %C = %ANGLE_PLAYER read at entry
    sh_reset(0);
    sh_sprite(0, TH16_SHARD, 4);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 11, 1);
    sh_speed(0, 4.0fx, 0fx);
    sh_offset(0, 0fx, -24fx);      // etOffset(0, 0, -24)
    sh_dist(0, 16fx);
    sh_reset(1);
    sh_sprite(1, TH16_SHARD, 4);
    sh_ring(1, 1);
    sh_aim(1, 0);
    sh_count(1, 11, 1);
    sh_speed(1, 3.8fx, 0fx);
    sh_offset(1, 0fx, -24fx);
    sh_dist(1, 16.8fx);
    for i in 0..30 {
        sh_angle(0, a, 0deg);      // etAngle(0, C, 0) then etOn(0)
        sh_angle(1, a, 0deg);
        sh_fire(0);
        sh_fire(1);
        a = a + step;              // C = C + A
        wait(5);
    }
}

// ---- moveRand(60,4,1.9) with moveLimit(0,128,240,64).
// Recipe: transcribe/th16/movement.md. Enemy slots: int0 = next step count,
// fx0/fx1 = logical unit direction. Limit rect x in [-120,120], y in [96,160];
// direction inner region x +-60, y 112..144.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.9fx * (60 - k) as fx / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

async sub boss8() {
    set_invuln(65535);
    set_hurtbox(20fx);                       // Boss(): setHurtbox(40,40) -> r=20
    set_hitbox(24fx);                        // Boss(): setHitbox(48,48) -> r=24
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);  // movePosTime(60,4,0,128); zero from (0,128)
    wait(120);                               // source wait(120) after setInvuln(120)
    // moveLimit(0,128,240,64) applies to card_arm_next_step's clamps.
    wait(60);                                // anmPlay/playSound block in source
    loop {
        spawn boss8_at(RING_STEP as angle);   // @Boss8_at(+0.113662824, ...) async
        wait(100);
        card_move_rand();                    // moveRand(60,4,1.9)
        card_wait(60);                       // source wait(60), also steps the moveRand
        spawn boss8_at((0 - RING_STEP) as angle);
        wait(100);
        card_move_rand();
        card_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 13400, 0, 0, 0, boss8);   // lifeSet(13400)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
